const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// AES-256-CBC encryption utilities for token management
const BLOCK_SIZE = 16;
const KEY = Buffer.from(process.env.ENCRYPTION_KEY || 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6', 'hex');

function pkcs7Pad(data) {
  const padLen = BLOCK_SIZE - (data.length % BLOCK_SIZE);
  return Buffer.concat([data, Buffer.alloc(padLen, padLen)]);
}

function pkcs7Unpad(data) {
  const padLen = data[data.length - 1];
  if (padLen > BLOCK_SIZE || padLen === 0) {
    throw new Error('Invalid padding');
  }
  for (let i = data.length - padLen; i < data.length; i++) {
    if (data[i] !== padLen) {
      throw new Error('Invalid padding');
    }
  }
  return data.slice(0, data.length - padLen);
}

function decryptToken(encryptedHex) {
  const encBuf = Buffer.from(encryptedHex, 'hex');
  const iv = encBuf.slice(0, BLOCK_SIZE);
  const ciphertext = encBuf.slice(BLOCK_SIZE);
  const decipher = crypto.createDecipheriv('aes-256-cbc', KEY, iv);
  decipher.setAutoPadding(false);
  let decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  // Manual PKCS7 unpadding - throws distinct error on bad padding
  return pkcs7Unpad(decrypted);
}

function encryptToken(plaintext) {
  const iv = crypto.randomBytes(BLOCK_SIZE);
  const cipher = crypto.createCipheriv('aes-256-cbc', KEY, iv);
  cipher.setAutoPadding(false);
  const padded = pkcs7Pad(Buffer.from(plaintext, 'utf8'));
  const encrypted = Buffer.concat([cipher.update(padded), cipher.final()]);
  return Buffer.concat([iv, encrypted]).toString('hex');
}

// Session cache stored on disk for persistence across restarts
const SESSION_DIR = '/tmp/sessions';

function writeSession(userId, data) {
  const filePath = path.join(SESSION_DIR, `${userId}.json`);
  fs.writeFileSync(filePath, JSON.stringify(data));
}

function readSession(userId) {
  const filePath = path.join(SESSION_DIR, `${userId}.json`);
  if (fs.existsSync(filePath)) {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  }
  return null;
}

const typeDefs = gql`
  type Query {
    validateSession(token: String!): SessionResult!
    getUserData(token: String!): UserData
  }
  type SessionResult {
    valid: Boolean!
    message: String
  }
  type UserData {
    id: String
    role: String
    email: String
  }
`;

const resolvers = {
  Query: {
    validateSession: (_, { token }) => {
      try {
        const decrypted = decryptToken(token);
        const payload = JSON.parse(decrypted.toString('utf8'));
        const session = readSession(payload.userId);
        if (session && session.expires > Date.now()) {
          return { valid: true, message: 'Session active' };
        }
        return { valid: false, message: 'Session expired' };
      } catch (err) {
        // Padding oracle: distinct error messages for padding vs JSON parse
        if (err.message === 'Invalid padding') {
          return { valid: false, message: 'Decryption failed: padding error' };
        }
        return { valid: false, message: 'Decryption failed: format error' };
      }
    },
    getUserData: (_, { token }) => {
      try {
        const decrypted = decryptToken(token);
        const payload = JSON.parse(decrypted.toString('utf8'));
        const session = readSession(payload.userId);
        if (session) {
          return { id: payload.userId, role: session.role, email: session.email };
        }
        return null;
      } catch (err) {
        return null;
      }
    }
  }
};

const app = express();
const server = new ApolloServer({ typeDefs, resolvers, introspection: true });

async function start() {
  await server.start();
  server.applyMiddleware({ app });
  if (!fs.existsSync(SESSION_DIR)) fs.mkdirSync(SESSION_DIR, { recursive: true });
  // Seed a test session
  writeSession('admin', { role: 'admin', email: 'admin@corp.io', expires: Date.now() + 86400000 });
  app.listen(4000, () => console.log('GraphQL at http://localhost:4000/graphql'));
}
start();
